-- Migration 014: Certification Runtime (Component #25)
--
-- Establishes the certifications table that persists every certification
-- evaluation generated by the Certification Runtime.  Each row records
-- the full evaluation result: score breakdown, control pass/fail, all
-- verification references, and evidence references.
--
-- Certification levels:
--   NOT_CERTIFIED      — score < 60 or any critical control failure
--   CERTIFIED          — score 60–79, no critical failures
--   CERTIFIED_PLUS     — score 80–94, no critical failures
--   CERTIFIED_PREMIUM  — score 95–100, no critical failures
--
-- Certification decisions:
--   CERTIFIED     — any non-NOT_CERTIFIED level
--   NOT_CERTIFIED — level is NOT_CERTIFIED
--
-- Architecture:
--   certifications — immutable append-only log of evaluation runs
--
-- Immutability enforcement:
--   • No UPDATE or DELETE policies (RLS INSERT-only for qodiqa_app).
--   • UNIQUE constraint on certification_id.
--
-- Integrates with:
--   attestations, portal_verifications, evidence_chain_records,
--   transparency_log_entries.
-- RLS: FORCE on all tables; qodiqa_app INSERT + SELECT; qodiqa_read SELECT.

BEGIN;

-- ── Certifications ────────────────────────────────────────────────────────────
--
-- Immutable append-only log of every certification evaluation.
-- INSERT-only. No UPDATE or DELETE.

CREATE TABLE IF NOT EXISTS certifications (
  id                        BIGSERIAL     PRIMARY KEY,

  -- Stable external identifier
  certification_id          UUID          NOT NULL DEFAULT gen_random_uuid(),

  -- Certification outcome
  certification_level       VARCHAR(30)   NOT NULL,
  certification_decision    VARCHAR(20)   NOT NULL,

  -- Compliance score (0–100)
  score                     SMALLINT      NOT NULL,
  score_breakdown           JSONB         NOT NULL DEFAULT '{}',

  -- Control results
  critical_control_failures JSONB         NOT NULL DEFAULT '[]',
  passed_controls           JSONB         NOT NULL DEFAULT '[]',
  failed_controls           JSONB         NOT NULL DEFAULT '[]',

  -- Full evaluation result (for evidence retrieval and report regeneration)
  evaluation_result         JSONB         NOT NULL DEFAULT '{}',

  -- Verification references
  attestation_references    JSONB         NOT NULL DEFAULT '[]',
  evidence_references       JSONB         NOT NULL DEFAULT '[]',
  verification_references   JSONB         NOT NULL DEFAULT '{}',

  -- Cryptographic anchoring
  transparency_id           UUID          NULL,      -- link to transparency_log_entries
  evidence_package_hash     CHAR(64)      NULL,      -- SHA-256 of certification evidence package

  -- Submission metrics
  artifacts_count           INTEGER       NOT NULL DEFAULT 0,
  evidence_packages_count   INTEGER       NOT NULL DEFAULT 0,

  -- Request metadata
  requested_by              VARCHAR(128)  NOT NULL DEFAULT 'external',
  request_ip                VARCHAR(64)   NULL,
  duration_ms               INTEGER       NULL,
  generated_at              TIMESTAMPTZ   NOT NULL DEFAULT NOW(),

  -- Constraints
  CONSTRAINT cert_id_unique       UNIQUE (certification_id),
  CONSTRAINT cert_score_range     CHECK (score >= 0 AND score <= 100),
  CONSTRAINT cert_evpkg_len       CHECK (evidence_package_hash IS NULL OR LENGTH(evidence_package_hash) = 64),
  CONSTRAINT cert_level_check     CHECK (certification_level IN (
    'NOT_CERTIFIED', 'CERTIFIED', 'CERTIFIED_PLUS', 'CERTIFIED_PREMIUM'
  )),
  CONSTRAINT cert_decision_check  CHECK (certification_decision IN (
    'CERTIFIED', 'NOT_CERTIFIED'
  ))
);

COMMENT ON TABLE certifications IS
  'Immutable log of every QODIQA certification evaluation. '
  'INSERT-only: certification history must never be modified or deleted. '
  'Each row records the full evaluation for compliance, audit, and regulatory review.';

COMMENT ON COLUMN certifications.certification_level IS
  'NOT_CERTIFIED: score < 60 or critical control failure. '
  'CERTIFIED: score 60–79, no critical failures. '
  'CERTIFIED_PLUS: score 80–94, no critical failures. '
  'CERTIFIED_PREMIUM: score 95–100, no critical failures.';

COMMENT ON COLUMN certifications.score IS
  'Compliance score 0–100. Derived from verification, operational, and compliance controls. '
  'A high score does not override a critical control failure.';

COMMENT ON COLUMN certifications.evidence_package_hash IS
  'SHA-256 of stableStringify(content) of the QODIQA::CERTIFICATION_EVIDENCE::V1 package. '
  'Enables offline integrity verification of the certification evidence.';

COMMENT ON COLUMN certifications.transparency_id IS
  'UUID of the transparency_log_entries row registered for this certification evaluation.';

-- ── Indexes ───────────────────────────────────────────────────────────────────

CREATE INDEX IF NOT EXISTS idx_cert_certification_id
  ON certifications (certification_id);

CREATE INDEX IF NOT EXISTS idx_cert_level
  ON certifications (certification_level, generated_at DESC);

CREATE INDEX IF NOT EXISTS idx_cert_decision
  ON certifications (certification_decision, generated_at DESC);

CREATE INDEX IF NOT EXISTS idx_cert_score
  ON certifications (score DESC, generated_at DESC);

CREATE INDEX IF NOT EXISTS idx_cert_generated_at
  ON certifications (generated_at DESC);

CREATE INDEX IF NOT EXISTS idx_cert_requested_by
  ON certifications (requested_by, generated_at DESC);

CREATE INDEX IF NOT EXISTS idx_cert_transparency_id
  ON certifications (transparency_id)
  WHERE transparency_id IS NOT NULL;

-- ── Row Level Security ────────────────────────────────────────────────────────

ALTER TABLE certifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE certifications FORCE ROW LEVEL SECURITY;

-- SELECT: all authenticated roles
CREATE POLICY cert_select
  ON certifications
  FOR SELECT TO qodiqa_app, qodiqa_read
  USING (true);

-- INSERT-only (no UPDATE, no DELETE)
CREATE POLICY cert_insert
  ON certifications
  FOR INSERT TO qodiqa_app
  WITH CHECK (true);

-- ── Grants ────────────────────────────────────────────────────────────────────

GRANT SELECT, INSERT ON certifications TO qodiqa_app;
GRANT SELECT         ON certifications TO qodiqa_read;
GRANT USAGE, SELECT  ON SEQUENCE certifications_id_seq TO qodiqa_app;

-- ── Migration record ──────────────────────────────────────────────────────────

INSERT INTO qodiqa_migrations (version, name, checksum, applied_by)
VALUES (14, 'certification_runtime', 'PLACEHOLDER_CHECKSUM', current_user)
ON CONFLICT (version) DO NOTHING;

COMMIT;
